import * as buffer from 'node:buffer';
function main(): void {
  const b: any = buffer;
  const calls: any[] = [() => b.atob(), () => b.btoa(), () => b.isUtf8(), () => b.isAscii()];
  for (const call of calls) {
    try { call(); console.log('no throw'); } catch (e: any) { console.log(e.name, e.code, e.message); }
  }
  console.log(b.isUtf8(new Uint8Array([0x68, 0x69])), b.isUtf8(new Uint8Array([0xff])), b.isAscii(new Uint8Array([0x80])), b.isAscii(new ArrayBuffer(2)));
  console.log(typeof b.resolveObjectURL, b.resolveObjectURL('blob:nodedata:missing'));
  console.log(b.atob('aGk='), b.btoa('hi'));
}
